const main = items[0].json;

const output = {
  time: main.meta.triggered_at,
  crop: main.crop ?? null,

  // only relevant actuator fields for notifications
  actuators: (main.actuators ?? []).map(a => ({
    type:            a.type,
    control_mode:    a.control_mode,
    classification:  a.classification,
    run: {
      execute_at:       a.run?.execute_at       ?? null,
      execute_until:    a.run?.execute_until     ?? null,
      duration_minutes: a.run?.duration_minutes  ?? null
    },
    recommended_action: a.recommended_action ?? null
  })),

  // only active warnings
  warnings: (main.warnings ?? [])
    .filter(w => w.active === true)
    .map(w => ({
      name:        w.name,
      severity:    w.severity,
      description: w.description
    })),

  // weather summary only, no insights
  weather: {
    state:                     main.weather.state,
    precipitation_probability: main.weather.precipitation_probability,
    summary:                   main.weather.summary
  }
};

return [{ json: output }];

